---@param name any
---@param args any
---@param ctx any
function paw.cmd(name, args, ctx) end

--- Run `fn` once, after `ms` milliseconds (or when the current turn ends).
---@param fn any
---@param ms any
function paw.defer(fn, ms) end

--- The device, clip or automation lane of an id, as an object.
---@param id any
function paw.device(id) end

--- Descriptions of each kind of device that you can add to a track. A kind
--- that an extension added (`paw.plugins.add_dir`) has its extension in `from`.
function paw.device_types() end

--- Call each handler for `event` (a name, or a descriptor). paw reports a handler that fails, and goes
--- to the next. Returns true, or false and the reason when a handler
--- returned `false, reason`. So a handler refuses the request of an event
--- (`edit.before`, `project.saving`, `key.pre`).
---@param event any
---@param payload any
function paw.emit(event, payload) end

--- Run `fn` every `ms` milliseconds. Returns a handle for `paw.cancel`.
---@param ms any
---@param fn any
function paw.every(ms, fn) end

--- What a user sees of an error: one line, without the list of calls.
--- The place in the code (`paw/x.lua:12:`) moves to the end, where it does
--- not hide what went wrong. The whole error goes to the log.
---@param err any
function paw.failure(err) end

--- Push the edits made until now to the engine, and send their change
--- events. The kernel does this at the end of each turn. Call `paw.flush()`
--- to make handlers run sooner.
function paw.flush() end

