--- one. Returns how many were removed, or nil and what is wrong.
---@param spec any
---@param all any
function paw.keymap.delmarks(spec, all) end

--- Handle one key as if the user typed it. The kernel calls this. Scripts use `feed`.
---@param key any
function paw.keymap.dispatch(key) end

--- Call `fn(map, mode, scope, keys)` for each mapping, in no order, with
--- `keys` joined as `put` takes them. It is `every` without the sort.
---@param fn any
function paw.keymap.each(fn) end

--- After an Escape that had nothing to cancel in the view: the listeners
--- of the `escape` event end what goes on (a count-in, a take, a render,
--- a snippet). When none of them ended anything, a second one within two
--- seconds outside the arrange view says how to leave: `how`, or the keys
--- that leave any view. A view that maps `<Esc>` calls it when it has
--- nothing of its own to cancel.
---@param how any
function paw.keymap.escape_hint(how) end

--- Every mapping in every mode and scope, sorted by scope, mode and keys.
--- What checks the key rules walks (`tests/keys_constitution.lua`).
function paw.keymap.every() end

--- Write `<leader>` and `<localleader>` as the keys the options name.
---@param lhs any
function paw.keymap.expand(lhs) end

--- Type keys as if from the keyboard: `paw.keymap.feed("jj<Space>")`.
---@param keys any
function paw.keymap.feed(keys) end

--- The first mapping of `mode` (in `view`, then global) that `test(map)`
--- is true for, in the order of `list`, with no list made and sorted.
---@param mode any
---@param test any
---@param view any
function paw.keymap.first(mode, test, view) end

--- What a register holds (the unnamed one when `name` is nil).
---@param name any
function paw.keymap.getreg(name) end

--- Move to a mark. With `'` or a backtick as the name, return to the start
--- of the last jump. With `.`, go to the place of the last edit.
---@param name any
function paw.keymap.goto_mark(name) end

--- Give a name to a prefix that only leads to more keys. The hints after it
--- then show `+mix`, not the number of keys after it.
---   paw.keymap.group("<leader>m", "mix")
--- With `opts.view`, the name applies only while that view has focus.
---@param prefix any
---@param name any
---@param opts any
function paw.keymap.group(prefix, name, opts) end

--- The name given to a prefix with `group`, if any.
---@param keys any
function paw.keymap.group_name(keys) end

--- The names given to prefixes with `group`: scope -> keys -> name.
function paw.keymap.groups() end

--- True if a mapping with the same keys and scope is also made in `mode`.
---@param mode any
---@param map any
function paw.keymap.has(mode, map) end

--- The keys that can come after the typed keys, when the user stops to
--- type: a list of { key, desc }, and a title. Nil when there is nothing to show.
function paw.keymap.hints() end

--- Keys as a person writes them: `<A-h>` is `Alt-h`, `<leader>at` is `Space at`,
--- `<localleader>d` is `\d`, `<C-w>o` is `Ctrl-w o`, `<CR>` is `Enter`. Takes an `lhs` or a list of keys.
---@param keys any
function paw.keymap.human(keys) end

--- Return through the places of the jumps (with a negative `n`, go forward again).
---@param n any
function paw.keymap.jump(n) end

--- The last selection made in the focused view, as `'<,'>` names it: the
--- one open now, or the one visual mode last closed. Nil if there is none.
function paw.keymap.last_selection() end

--- Mappings that apply in `mode` for `view`, the view's own first.
---@param mode any
---@param view any
function paw.keymap.list(mode, view) end

--- Set mark `name` (a letter) at the cursor of the focused view.
---@param name any
function paw.keymap.mark(name) end

--- The marks of a view: name -> position.
---@param view any
function paw.keymap.marks(view) end

--- Type keys from inside a mapping, as `:normal` does. The keys run as a
--- part of the current command, not as a separate command.
---@param keys any
function paw.keymap.normal(keys) end

--- Run `fn` once, before the next key is handled: for what waits until the
--- person is back at the keyboard (a file changed outside paw).
---@param fn any
function paw.keymap.on_next_key(fn) end

--- Define an operator: `fn(region, ctx)` acts on a region of the focused
--- view. A region has `r0`, `r1` (rows, inclusive), `c0`, `c1` (beats, the
--- end not included) and `kind`: "char" for a stretch of time, "line" for
--- whole rows, "block" for a rectangle.
---   paw.keymap.operator("gl", function(region) ... end, { view = "arrange", desc = "Loop" })
--- With `count = "operator"`, the count typed before the operator is its
--- own, as `ctx.op_count`. It tells how far or how many times: `3gUib` is
--- three steps up over a bar. `ctx.count` is the count of the motion or
--- object alone.
---@param lhs any
---@param fn any
---@param opts any
function paw.keymap.operator(lhs, fn, opts) end

--- Split `gg<C-x>` into { "g", "g", "<C-x>" }, and expand `<leader>` and `<localleader>`.
---@param lhs any
function paw.keymap.parse(lhs) end

--- The keys typed for a command that is not complete, for display: `"a2d3`.
function paw.keymap.pending() end

--- Play the keys in a register `n` times. `@` as the name plays the last register again.
---@param name any
---@param n any
function paw.keymap.play(name, n) end

--- Remember where the cursor is before it goes somewhere far away.
function paw.keymap.push_jump() end

--- Put a mapping back as `map` (a mapping that `every` gave), or remove it
--- with nil. The mapping is found by its mode, scope and joined keys
--- (`table.concat(map.keys)`). An extension that unloads does this with
--- the keys that it mapped.
---@param mode any
---@param scope any
---@param keys any
---@param map any
function paw.keymap.put(mode, scope, keys, map) end

--- Start recording keys into a register, or stop with no name.
---@param name any
function paw.keymap.record(name) end

--- The register being recorded into, if any.
function paw.keymap.recording() end

--- Make `.` repeat `keys` (a list of keys), not the keys typed for the
--- command that runs now. `:adjust` does it, so that `.` does the adjusted
--- command again.
---@param keys any
function paw.keymap.repeat_as(keys) end

--- Do the last change again, with `n` in place of its count if given.
---@param n any
function paw.keymap.repeat_last(n) end

--- Where paw finds mappings, first to last. First comes the part of the
--- focused view that has the cursor, if the view has such parts
--- (`view:subscope()`). For example, "arrange.lane" on an automation lane
--- row, or a list of parts, the first part first. Then comes the view,
--- then all views.
function paw.keymap.scopes() end

--- Search the focused view for `text`, forward (`dir` 1) or back (-1).
---@param text any
---@param dir any
function paw.keymap.search(text, dir) end

--- Move to the next (`dir` 1) or previous (-1) thing in the focused view that
--- matches the last search. Views say what matches through `grid.search`.
---@param dir any
---@param n any
function paw.keymap.search_next(dir, n) end

--- The region selected in the focused view, or nil outside visual mode. It
--- goes from the cursor to the start of the selection. Both ends are
--- included when the view tells the size of the item under the cursor
--- (`grid.extent`). A selection that did not grow covers one grid step.
--- While a command runs with `:'<,'>`, it is the selection that the command names.
function paw.keymap.selection() end

--- Map keys.
---   paw.keymap.set("M", "track.mute", { desc = "Mute track" })
---   paw.keymap.set("<leader>mz", function(ctx) ... end, { desc = "Check the mix" })
--- `ctx` has `count`, `register` and, for mappings made with `char = true`,
--- the key typed after the mapping as `char`.
--- 
--- The options are `mode` (one mode or a list, default "n"), `view` and
--- `desc`. `motion = true` is for a mapping that only moves the cursor.
--- Such a mapping also works in visual mode and after an operator.
--- 
--- `linewise = true` is for a motion across rows. `jump = true` keeps the
--- position of the cursor for `<C-o>`. With `repeatable = false`, `.` does
--- not repeat the mapping. `nowait = true` makes a key that also starts
--- longer mappings run at once, without the wait for more keys.
--- 
--- Each key with `role` "second+" or "second-" (the `[` and `]` of a view)
--- does so. The same key again is a second press. Another key soon after
--- it that makes a longer mapping (`]g`, `]q`) takes back its change and runs
--- that mapping. On a selection, the selection opens again for that mapping.
---@param lhs any
---@param rhs any
---@param opts any
function paw.keymap.set(lhs, rhs, opts) end

--- Change mode. When visual mode stops, the selection closes. `gv` opens it again.
---@param mode any
function paw.keymap.set_mode(mode) end

--- Put a value in a register: the unnamed register, and `name` if given.
--- With `yank` and no name, it also goes to `"0`, which a delete never
--- changes. A value is a table with a `kind`. The code that yanks and
--- pastes it decides what else it contains. `"_` discards.
---@param value any
---@param name any
---@param yank any
function paw.keymap.setreg(value, name, yank) end

--- What belongs to a project, for `paw.shada`: the marks, the jump lists
--- (without where `<C-o>` is) and the places of the edits, each by view.
function paw.keymap.shada_project() end

--- Put back what `shada_project` gave, in place of the marks and places now.
---@param data any
function paw.keymap.shada_set_project(data) end

--- Put back what `shada_user` gave.
---@param data any
function paw.keymap.shada_set_user(data) end

--- What belongs to the user, for `paw.shada`: the last search and the
--- registers (as a table of registers by name).
function paw.keymap.shada_user() end

--- Define a text object: `fn(ctx)` returns a region, or nil when there is
--- nothing of that kind at the cursor.
---   paw.keymap.textobject("ic", function() ... end, { view = "arrange", desc = "The clip" })
---@param lhs any
---@param fn any
---@param opts any
function paw.keymap.textobject(lhs, fn, opts) end

--- Open the last selection again.
function paw.keymap.visual_restore() end

--- Start a selection from the cursor: "v" a range of time, "V" whole rows,
--- "b" a rectangle. The same kind again stops visual mode.
---@param kind any
function paw.keymap.visual_start(kind) end

--- Swap the cursor with the selection's other end.
function paw.keymap.visual_swap() end

--- Run `fn(...)` with `region` as the selection, the way `:'<,'>` runs a
--- command: anything that asks for the selection meanwhile gets it.
---@param region_ any
---@param fn any
function paw.keymap.with_selection(region_, fn, ...) end

--- Every mapping that breaks the rule, as "scope mode keys: why", sorted.
--- Insert mode is left out (its keys enter material), and so are keys
--- made with `prompt = true`, which answer a question on the screen.
function paw.keyrule.broken() end

--- Named groups of keys that lead to no key, as "scope keys (name)".
function paw.keyrule.lost_groups() end

--- True if a track has its lanes open.
function paw.lanes.any_open() end

--- Change the lane's points with `fn(points)`, which edits the list in place.
---@param lane_id any
---@param fn any
function paw.lanes.edit(lane_id, fn) end

--- A value of a lane as its target shows it: "-6.0 dB", "L30", "800 Hz".
---@param lane any
---@param value any
function paw.lanes.format(lane, value) end

--- True if the lanes of a track show as rows.
---@param track any
function paw.lanes.is_open(track) end

--- Every row of the arrange view in order: each track drawn, then its lanes
--- when they are open.
function paw.lanes.lines() end

--- What a lane is called: Volume, Pan, or its device and parameter.
---@param lane any
function paw.lanes.name(lane) end

--- Show a track's lanes as rows, or hide them (`on` false).
---@param track any
---@param on any
function paw.lanes.open(track, on) end

--- The parameter a lane moves: its name, and the parameter's description
--- for a device's lane.
---@param lane any
function paw.lanes.param_of(lane) end

--- The point at a beat, within `reach` beats: its index in the lane's
--- points, and the point { beat, value }.
---@param lane_id any
---@param beat any
---@param reach any
function paw.lanes.point_at(lane_id, beat, reach) end

--- The lanes shown under a track: none when they are closed.
---@param track any
function paw.lanes.shown(track) end

--- How far `+` and `-` move a point: a dB, 5% of pan, one choice, or a
--- hundredth of the parameter's range.
