---   paw.option.define("lanes", 4, { min = 1, max = 16, integer = true })
---   paw.option.define("look", "plain", { values = { "plain", "fancy" } })
---   paw.option.define("size", "auto", { type = { "number", "string" }, min = 1, values = { "auto" } })
--- It gives a handle with the type of the default: `get()` and `set(value)`.
---@param name any
---@param default any
---@param spec any
function paw.option.define(name, default, spec) end

--- Each option given a default by `paw.option.define`, by name: what it
--- was given, `{ default, spec }`, the same table until defined again.
function paw.option.definitions() end

--- The full name of option `name`: itself, or what its short name stands for.
---@param name any
function paw.option.full(name) end

--- Every option that has a default, by name: { name, default }.
function paw.option.list() end

--- The value typed text stands for in option `name` (`true`, `off`, a
--- number, the text, or a list for an option that takes one: `a,b`), or
--- nil and an error that says what it takes. A value that is not text is
--- checked as it is.
---@param name any
---@param text any
function paw.option.read(name, text) end

--- Give each option the value it had in `snapshot`, and an option set
--- after it its default again. Each option that changes emits
--- `option.changed`. Gives the names of the options that changed, sorted.
---@param snapshot any
function paw.option.restore(snapshot) end

--- An option's value as text: a list is its items with commas between.
---@param value any
function paw.option.show(value) end

--- The value of each option that was set, to give back later with
--- `paw.option.restore`. An option that was not set keeps its default.
function paw.option.snapshot() end

--- What option `name` takes besides its default's type (`min`, `max`,
--- `integer`, `type`, `values`), or nil.
---@param name any
function paw.option.spec(name) end

--- The size of the main area in pixels, from the frontend: at the start
--- and each time that it changes. The first time that the window of a seat
--- gives it, paw shows the device panel when the tab has its place, closed,
--- as the default start layout has (`paw.layout.default_tree`): a window
--- shows the devices of the selected track next to the timeline unless the
--- user closes them. A start layout of the configuration's own is shown as
--- it is.
---@param width any
---@param height any
function paw.panes.area(width, height) end

--- A border of the last arrangement (by its place in `state().borders`)
--- dragged to `x, y`: as a border dragged in the terminal, the side that
--- has a size keeps one, in whole cells.
---@param index any
---@param x any
---@param y any
function paw.panes.border(index, x, y) end

--- The main area in cells, with the status line and the command line
--- under it as on a terminal: what the seat's screen is. Nil until the
--- frontend has said.
function paw.panes.cells() end

--- Close a pane's window, as `:close` in it would.
---@param id any
function paw.panes.close(id) end

--- Give a pane's window the keyboard, as a click in it does.
---@param id any
function paw.panes.focus(id) end

--- A pointer event in a pane, in pixels from its corner (as
--- `paw.canvas.pointer` takes them). A press gives it the keyboard first.
--- For a pane drawn in cells, `drawn` tells how: its `cell`, and its size
--- in cells, `cols` and `rows`. It keeps the button held in a drag.
---@param id any
---@param event any
---@param drawn any
function paw.panes.pointer(id, event, drawn) end

--- The positions of all items in the main area, for the state of a
--- frontend. `panes` is a list of `{ win, view, kind ("native", "paint",
--- "cells"), title, x, y, w, h, focused, titled }`. `borders` is a list of
--- `{ dir, x, y, length }`. For `dir`, "h" is a rule between panes side by
--- side, and "v" is a rule between panes one above the other. `tabs` is a list of
--- `{ title }`, and `tab` is the current tab. `top` is where the panes
--- start, below the row of tabs. Nil until the frontend gives the size of
--- its area.
function paw.panes.state() end

--- A click on tab `i` goes to it.
